function o(t){if(!t||t<=0)return"0 B";const e=["B","KB","MB","GB","TB","PB"];let r=0,n=t;for(;n>=1024&&r<e.length-1;)n/=1024,r++;return`${n>=100?Math.round(n):n.toFixed(1)} ${e[r]}`}function a(t){if(!t)return"never";const e=t.includes("T")?new Date(t).getTime():new Date(t.replace(" ","T")+"Z").getTime();if(isNaN(e))return t;const r=Math.max(0,(Date.now()-e)/1e3);return r<60?`${Math.floor(r)}s ago`:r<3600?`${Math.floor(r/60)}m ago`:r<86400?`${Math.floor(r/3600)}h ago`:`${Math.floor(r/86400)}d ago`}function f(t){if(!t||t<=0)return"—";const e=Math.floor(t/86400),r=Math.floor(t%86400/3600),n=Math.floor(t%3600/60);return e>0?`${e}d ${r}h`:r>0?`${r}h ${n}m`:`${n}m`}export{f as a,o as f,a as t};
